CREATE TABLE IF NOT EXISTS users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','editor') NOT NULL DEFAULT 'admin',is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS project_categories (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL UNIQUE,slug VARCHAR(170) NOT NULL UNIQUE,description TEXT NULL,is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS services (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL UNIQUE,slug VARCHAR(170) NOT NULL UNIQUE,is_active TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS projects (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category_id INT UNSIGNED NOT NULL,title VARCHAR(220) NOT NULL,slug VARCHAR(240) NOT NULL UNIQUE,project_type VARCHAR(150) NULL,location VARCHAR(190) NULL,city VARCHAR(100) NULL,state VARCHAR(100) NULL,country VARCHAR(100) NOT NULL DEFAULT 'India',short_description VARCHAR(500) NULL,overview LONGTEXT NULL,design_concept LONGTEXT NULL,highlights LONGTEXT NULL,construction_details LONGTEXT NULL,materials LONGTEXT NULL,special_features LONGTEXT NULL,h1_heading VARCHAR(255) NULL,cover_image VARCHAR(255) NULL,cover_image_public TINYINT(1) NOT NULL DEFAULT 0,cover_image_approved TINYINT(1) NOT NULL DEFAULT 0,hero_image VARCHAR(255) NULL,hero_image_public TINYINT(1) NOT NULL DEFAULT 0,hero_image_approved TINYINT(1) NOT NULL DEFAULT 0,status ENUM('draft','published','archived') NOT NULL DEFAULT 'draft',completion_year SMALLINT NULL,is_featured TINYINT(1) NOT NULL DEFAULT 0,display_order INT NOT NULL DEFAULT 0,robots_index TINYINT(1) NOT NULL DEFAULT 1,created_by INT UNSIGNED NULL,updated_by INT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_projects_category FOREIGN KEY(category_id) REFERENCES project_categories(id),CONSTRAINT fk_projects_creator FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL,CONSTRAINT fk_projects_updater FOREIGN KEY(updated_by) REFERENCES users(id) ON DELETE SET NULL,INDEX idx_project_status(status),INDEX idx_project_category(category_id),INDEX idx_project_city(city),INDEX idx_project_featured(is_featured)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS project_services (project_id BIGINT UNSIGNED NOT NULL,service_id INT UNSIGNED NOT NULL,PRIMARY KEY(project_id,service_id),FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE,FOREIGN KEY(service_id) REFERENCES services(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS category_fields (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category_id INT UNSIGNED NOT NULL,field_key VARCHAR(100) NOT NULL,label VARCHAR(150) NOT NULL,input_type ENUM('text','textarea','number','select','multiselect','boolean','year') NOT NULL DEFAULT 'text',options_json JSON NULL,unit VARCHAR(40) NULL,is_required TINYINT(1) NOT NULL DEFAULT 0,sort_order INT NOT NULL DEFAULT 0,is_active TINYINT(1) NOT NULL DEFAULT 1,UNIQUE KEY uq_category_field(category_id,field_key),FOREIGN KEY(category_id) REFERENCES project_categories(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS project_field_values (project_id BIGINT UNSIGNED NOT NULL,field_id INT UNSIGNED NOT NULL,value_json JSON NULL,visibility ENUM('public','private','optional') NOT NULL DEFAULT 'public',PRIMARY KEY(project_id,field_id),FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE,FOREIGN KEY(field_id) REFERENCES category_fields(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS project_contents (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,project_id BIGINT UNSIGNED NOT NULL,section_key VARCHAR(100) NOT NULL,heading VARCHAR(220) NULL,body LONGTEXT NULL,is_public TINYINT(1) NOT NULL DEFAULT 1,sort_order INT NOT NULL DEFAULT 0,FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE,INDEX(project_id,sort_order)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS project_images (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,project_id BIGINT UNSIGNED NOT NULL,file_path VARCHAR(255) NOT NULL,alt_text VARCHAR(255) NULL,caption VARCHAR(255) NULL,is_public TINYINT(1) NOT NULL DEFAULT 0,is_approved TINYINT(1) NOT NULL DEFAULT 0,is_cover TINYINT(1) NOT NULL DEFAULT 0,sort_order INT NOT NULL DEFAULT 0,uploaded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE,INDEX(project_id,is_public,is_approved)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS project_faqs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,project_id BIGINT UNSIGNED NOT NULL,question VARCHAR(500) NOT NULL,answer TEXT NOT NULL,is_public TINYINT(1) NOT NULL DEFAULT 1,sort_order INT NOT NULL DEFAULT 0,FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS project_seo (project_id BIGINT UNSIGNED PRIMARY KEY,seo_title VARCHAR(255) NULL,meta_description VARCHAR(320) NULL,focus_keyword VARCHAR(190) NULL,secondary_keywords TEXT NULL,canonical_url VARCHAR(500) NULL,og_title VARCHAR(255) NULL,og_description VARCHAR(320) NULL,og_image VARCHAR(255) NULL,schema_type VARCHAR(60) NOT NULL DEFAULT 'WebPage',FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS related_projects (project_id BIGINT UNSIGNED NOT NULL,related_project_id BIGINT UNSIGNED NOT NULL,sort_order INT NOT NULL DEFAULT 0,PRIMARY KEY(project_id,related_project_id),FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE,FOREIGN KEY(related_project_id) REFERENCES projects(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS project_revisions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,project_id BIGINT UNSIGNED NOT NULL,user_id INT UNSIGNED NULL,revision_data LONGTEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS page_views (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,project_id BIGINT UNSIGNED NOT NULL,visitor_hash CHAR(64) NOT NULL,viewed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE,INDEX idx_views_project_date(project_id,viewed_at),INDEX idx_views_date(viewed_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS activity_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NULL,project_id BIGINT UNSIGNED NULL,action VARCHAR(100) NOT NULL,details TEXT NULL,ip_address VARCHAR(45) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS settings (setting_key VARCHAR(100) PRIMARY KEY,setting_value TEXT NULL) ENGINE=InnoDB;
